-- Generated by scripts/build-seed.js from data.js — don't edit by hand.
-- Part 1 of 1 (300 people). Run schema.sql first, then every part
-- in the Supabase SQL editor, in order. Safe to re-run: existing people are
-- updated by name, new ones are added, and the last part removes anyone who
-- is no longer in the list.

on conflict (name) do update set
  answers = excluded.answers, hint = excluded.hint, fame = excluded.fame, wikidata = excluded.wikidata,
  born_year = excluded.born_year, born_lat = excluded.born_lat, born_lng = excluded.born_lng, born_place = excluded.born_place,
  died_year = excluded.died_year, died_lat = excluded.died_lat, died_lng = excluded.died_lng, died_place = excluded.died_place;

-- Remove people who are no longer in the list.
delete from public.people where name <> all (array['William Shakespeare', 'Adolf Hitler', 'Michael Jackson', 'Albert Einstein', 'Aristoteles', 'Konfucius', 'Karl Marx', 'Leonardo da Vinci', 'Ronald Reagan', 'Isaac Newton', 'Abraham Lincoln', 'Vladimir Lenin', 'Nelson Mandela', 'Muhammed', 'Napoleon I', 'Mahatma Gandhi', 'Lev Tolstoj', 'Julius Caesar', 'Charles Darwin', 'Josef Stalin', 'Johann Wolfgang von Goethe', 'Sokrates', 'George Washington', 'Wolfgang Amadeus Mozart', 'Ludwig van Beethoven', 'Dante Alighieri', 'Galileo Galilei', 'Victor Hugo', 'Vincent van Gogh', 'Pablo Picasso', 'Alexander den store', 'Charlie Chaplin', 'Winston Churchill', 'Michelangelo', 'Johann Sebastian Bach', 'Martin Luther', 'Voltaire', 'Fjodor Dostojevskij', 'Friedrich Nietzsche', 'Elizabeth II av Storbritannien', 'René Descartes', 'Thomas Edison', 'Mustafa Kemal Atatürk', 'Immanuel Kant', 'Sigmund Freud', 'Mark Twain', 'John F. Kennedy', 'Miguel de Cervantes', 'Charles Dickens', 'Marie Curie', 'Martin Luther King', 'Salvador Dalí', 'Rabindranath Tagore', 'Franklin D. Roosevelt', 'Arkimedes', 'Vergilius', 'Augustus', 'Aleksandr Pusjkin', 'Christofer Columbus', 'H.C. Andersen', 'Franz Kafka', 'Marilyn Monroe', 'Anton Tjechov', 'Franciskus', 'Jean-Jacques Rousseau', 'Mao Zedong', 'Steve Jobs', 'Niccolò Machiavelli', 'Che Guevara', 'Augustinus', 'Molière', 'Edgar Allan Poe', 'Thomas Jefferson', 'Adam Smith', 'Oscar Wilde', 'Charles de Gaulle', 'Nikola Tesla', 'Neil Armstrong', 'George Gordon Byron', 'Otto von Bismarck', 'Walt Disney', 'Benjamin Franklin', 'Elvis Presley', 'Carl von Linné', 'Sofokles', 'Nicolaus Copernicus', 'Louis Pasteur', 'George Orwell', 'Marco Polo', 'John Locke', 'Ernest Hemingway', 'Thomas av Aquino', 'Djingis khan', 'Margaret Thatcher', 'James Joyce', 'Johannes Paulus II', 'Rembrandt', 'Gabriel García Márquez', 'Richard Wagner', 'Fidel Castro', 'Gottfried Wilhelm Leibniz', 'Albert Camus', 'J.R.R. Tolkien', 'Jurij Gagarin', 'Jane Austen', 'Henry Ford', 'Cicero', 'Mar